import{z as i,x as l,o as t,c as d,q as o,j as s,D as e,d as n,s as A,S as C,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SCCP","description":"","frontmatter":{"title":"SCCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sccp.md","filePath":"cs/sccp.md","lastUpdated":1791063341000}'),B={name:"cs/sccp.md"};function p(c,a,S,P,m,D){const r=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="sccp" tabindex="-1">SCCP <a class="header-anchor" href="#sccp" aria-label="Permalink to &quot;SCCP&quot;">​</a></h1><div class="epigraph"><p>稀疏条件常量传播同时走 SSA 的 def-use 与 CFG 的可执行边：未执行的枝不产生常量冲突，于是更多名变成常量。</p><footer>—— 据 Wegman and Zadeck, Constant Propagation with Conditional Branches, 1991；Cytron SSA 论文对照整理</footer></div><p>上一课<a href="/cs/constant-propagation">常量传播</a>在「所有到达定值」上取交，死枝上的写仍会把格打成非常量。缺口是 <strong>SCCP</strong>：只沿可能执行的边传播，φ 只合并已执行前驱。本课钉工作表与可执行标志，不重写简单传播的折叠规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>if (1) x=2; else x=3;</code> 简单交得「非常量」，其实 \\(x=2\\)。SCCP：边先标不可执行，常量条件为真则只放行真枝。缺口是<strong>控制流与数据流联立</strong>，不是新的折叠表。<span class="marginnote">数字实例：条件折叠成真后，else 边永远不被标成可执行——φ(x) 只看见 \\(x=2\\) 这一个活前驱，格上停在常量 2；简单交法把死枝上的 3 也合并进来，只能给「非常量」。死枝不产生冲突，正是 SCCP 比简单传播准的全部原因。</span></p><p>稀疏：用 SSA 的 use 链当工作表，不扫全部程序点。这与稀疏数据流家族一致。</p><h3 id="「可执行」是分析结论" tabindex="-1">「可执行」是分析结论 <a class="header-anchor" href="#「可执行」是分析结论" aria-label="Permalink to &quot;「可执行」是分析结论&quot;">​</a></h3><p>未访问边当不执行是可靠近似的一边：永远不把死枝当活。反面：条件未知则两边都活，退回简单传播。不要把 SCCP 当路径敏感的全部符号执行。</p><p><span class="marginnote">Wegman–Zadeck 1991（TOPLAS）。Clang/LLVM 的 SCCP/IPSCCP 是工程后裔。本课过程内；过程间是 IPSCCP，后课过程间分析点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>格：未定义 / 常量 / overdefined。工作表：SSA 边与 CFG 边。规则：操作数 overdefined 则结果 overdefined；常量则折；φ 忽略不可执行前驱。分支：条件为常量则只标记一侧边。<span class="marginnote">术语翻译：「未定义」与「overdefined」是格的两个端点——未定义是「还没看到任何证据」的乐观起点（先赌它可能是常量），overdefined 是「证据打架」的悲观终点（相互矛盾的定值把它喂到无法再用单个常量描述，只能放弃替换）。分析从乐观端往悲观端走，只此一个方向。</span></p>',11)),(t(),s(C,null,{default:e(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SSA%5B%22SSA%20%2B%20CFG%22%5D%20--%3E%20WL%5B%22%E5%B7%A5%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20WL%20--%3E%20EDGE%5B%22%E6%A0%87%E8%AE%B0%E5%8F%AF%E6%89%A7%E8%A1%8C%E8%BE%B9%22%5D%0A%20%20WL%20--%3E%20VAL%5B%22%E6%A0%BC%E4%B8%8A%E7%9A%84%E5%80%BC%22%5D%0A%20%20EDGE%20--%3E%20PHI%5B%22%CF%86%20%E5%8F%AA%E5%B9%B6%E6%B4%BB%E5%89%8D%E9%A9%B1%22%5D%0A%20%20VAL%20--%3E%20EDGE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"实现：未定义与 overdefined 的次序要按论文：先当未定义，避免乐观错误。Wegman–Zadeck 给了格与初始化。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"与死代码：不可执行块可删，但正式 ADCE 下一课。SCCP 露出的常量调用可能变成死参数。",-1)),(t(),s(C,null,{default:e(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOT%5B%22%E2%8A%A5%20%E6%9C%AA%E5%AE%9A%E4%B9%89%EF%BC%9A%E8%BF%98%E6%B2%A1%E7%9C%8B%E5%88%B0%E4%BB%BB%E4%BD%95%E5%AE%9A%E5%80%BC%22%5D%20--%3E%7C%22%E7%9C%8B%E5%88%B0%E7%AC%AC%E4%B8%80%E4%B8%AA%E5%AE%9A%E5%80%BC%20x%3D2%22%7C%20C%5B%22%E5%B8%B8%E9%87%8F%202%22%5D%0A%20%20BOT%20--%3E%7C%22%E4%B8%A4%E4%B8%AA%E5%89%8D%E9%A9%B1%E7%BB%99%E7%9A%84%E5%AE%9A%E5%80%BC%E4%B8%8D%E5%90%8C%22%7C%20TOP%5B%22%E2%8A%A4%20overdefined%22%5D%0A%20%20C%20--%3E%7C%22%E5%8F%88%E8%A7%81%E5%88%B0%20x%3D3%22%7C%20TOP%0A%20%20C%20--%3E%7C%22%CF%86%20%E5%BF%BD%E7%95%A5%E4%B8%8D%E5%8F%AF%E6%89%A7%E8%A1%8C%E5%89%8D%E9%A9%B1%22%7C%20STAY%5B%22%E5%81%9C%E5%9C%A8%202%EF%BC%9A%E5%8F%AF%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20TOP%20--%3E%20NORET%5B%22%E4%B8%8D%E5%86%8D%E5%9B%9E%E5%A4%B4%EF%BC%9A%E6%A0%BC%E5%8D%95%E5%90%91%E4%B8%8B%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>过程间：若形参在所有活调用点是同一常量，可钉死——需调用图，后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写符号执行的路径爆炸。后课默认：条件常量用 SCCP。下一课 CSE/GVN：相等的是表达式，不只是立即数。</p><p>也不把 SCCP 当证明助手。<span class="marginnote">初学者容易把 SCCP 当成路径敏感分析的全部，实际上它只按「边是否可执行」做粗粒度的可行域收缩：同一条路径内部的条件关联（如前面算出 \\(x\\lt y\\)、后面又判 \\(x\\lt y\\)）它看不见——那是符号执行与路径敏感分析的领地。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SCCP：可执行边 + SSA 稀疏传播。</li><li>死枝不参与 φ，精度高于简单交。</li><li>条件未知则两边都活。</li><li>出处：Wegman and Zadeck, 1991；对照 Cytron SSA、龙书常量传播。</li></ul>',6))])}const u=i(B,[["render",p]]);export{h as __pageData,u as default};
